SELECT e.subject AS source_id, e.object AS target_id, e.authority, e.release
FROM ${catalog}.clinical_study_standards.kb_edge e
JOIN ${catalog}.clinical_study_graph.kb_node s ON s.concept_id = e.subject
JOIN ${catalog}.clinical_study_graph.kb_node o ON o.concept_id = e.object
WHERE e.predicate = 'cdisc:nciConcept' AND s.graph_class = 'CodelistTerm' AND o.graph_class = 'ReferenceConcept';

