CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_version_of__study_version__study COMMENT "StudyVersion versionOf Study" AS
SELECT study_version_id AS source_id, study_id AS target_id FROM ${catalog}.clinical_study_standards.study_version;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_screened_for__participant__study COMMENT "Participant screenedFor Study" AS
SELECT USUBJID AS source_id, STUDYID AS target_id FROM ${catalog}.clinical_study.silver_dm;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_at_site__participant__site COMMENT "Participant atSite Site" AS
SELECT USUBJID AS source_id, SITEID AS target_id FROM ${catalog}.clinical_study.silver_dm;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_medical_history__participant__medical_history_record COMMENT "Participant hasMedicalHistory MedicalHistoryRecord" AS
SELECT USUBJID AS source_id, CPL_SOURCE_RECORD_ID AS target_id FROM ${catalog}.clinical_study.silver_mh;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_coded_as__medical_history_record__disease COMMENT "MedicalHistoryRecord codedAs Disease" AS
SELECT CPL_SOURCE_RECORD_ID AS source_id, CPL_MONDO_ID AS target_id FROM ${catalog}.clinical_study.silver_mh WHERE CPL_CODING_STATUS = 'RESOLVED';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_con_med__participant__con_med_record COMMENT "Participant hasConMed ConMedRecord" AS
SELECT USUBJID AS source_id, CPL_SOURCE_RECORD_ID AS target_id FROM ${catalog}.clinical_study.silver_cm;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_coded_as__con_med_record__drug COMMENT "ConMedRecord codedAs Drug" AS
SELECT CPL_SOURCE_RECORD_ID AS source_id, CPL_RXNORM_ID AS target_id FROM ${catalog}.clinical_study.silver_cm WHERE CPL_CODING_STATUS = 'RESOLVED';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_observation__participant__weight_observation COMMENT "Participant hasObservation WeightObservation" AS
SELECT USUBJID AS source_id, CPL_OBS_ID AS target_id FROM ${catalog}.clinical_study.silver_vs WHERE VSTESTCD = 'WEIGHT';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_originates_from__weight_observation__source_record COMMENT "WeightObservation originatesFrom SourceRecord" AS
SELECT CPL_OBS_ID AS source_id, CPL_SOURCE_RECORD_ID AS target_id FROM ${catalog}.clinical_study.silver_vs WHERE VSTESTCD = 'WEIGHT';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_measures__weight_observation__biomedical_concept COMMENT "WeightObservation measures BiomedicalConcept" AS
SELECT CPL_OBS_ID AS source_id, 'COSMOS_BC:C81328' AS target_id FROM ${catalog}.clinical_study.silver_vs WHERE VSTESTCD = 'WEIGHT';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_conforms_to__weight_observation__dataset_specialization COMMENT "WeightObservation conformsTo DatasetSpecialization" AS
SELECT CPL_OBS_ID AS source_id, 'COSMOS_DSS:WEIGHT' AS target_id FROM ${catalog}.clinical_study.silver_vs WHERE VSTESTCD = 'WEIGHT';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_unit__weight_observation__codelist_term COMMENT "WeightObservation hasUnit CodelistTerm" AS
SELECT v.CPL_OBS_ID AS source_id, k.concept_id AS target_id FROM ${catalog}.clinical_study.silver_vs v JOIN ${catalog}.clinical_study_standards.kb_concept k ON k.notation = v.VSORRESU AND k.concept_id LIKE 'CDISC_CT:C66770.%' WHERE v.VSTESTCD = 'WEIGHT';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_for_participant__endpoint_result__participant COMMENT "EndpointResult forParticipant Participant" AS
SELECT concat(USUBJID, '.', endpoint_version) AS source_id, USUBJID AS target_id FROM ${catalog}.clinical_study.gold_endpoint_result;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_derived_under__endpoint_result__endpoint_rule_version COMMENT "EndpointResult derivedUnder EndpointRuleVersion" AS
SELECT concat(USUBJID, '.', endpoint_version) AS source_id, endpoint_version AS target_id FROM ${catalog}.clinical_study.gold_endpoint_result;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_uses_baseline_observation__endpoint_result__weight_observation COMMENT "EndpointResult usesBaselineObservation WeightObservation" AS
SELECT concat(USUBJID, '.', endpoint_version) AS source_id, explode(split(baseline_observation_id, ',')) AS target_id FROM ${catalog}.clinical_study.gold_endpoint_result WHERE baseline_observation_id IS NOT NULL;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_uses_followup_observation__endpoint_result__weight_observation COMMENT "EndpointResult usesFollowupObservation WeightObservation" AS
SELECT concat(USUBJID, '.', endpoint_version) AS source_id, followup_observation_id AS target_id FROM ${catalog}.clinical_study.gold_endpoint_result WHERE followup_observation_id IS NOT NULL;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_generated_by__endpoint_result__execution_run COMMENT "EndpointResult generatedBy ExecutionRun" AS
SELECT concat(USUBJID, '.', endpoint_version) AS source_id, execution_run_id AS target_id FROM ${catalog}.clinical_study.gold_endpoint_result;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_version_of_endpoint__endpoint_rule_version__endpoint_definition COMMENT "EndpointRuleVersion versionOfEndpoint EndpointDefinition" AS
SELECT endpoint_version AS source_id, endpoint_id AS target_id FROM ${catalog}.clinical_study_standards.rule_version;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_amends__endpoint_rule_version__endpoint_rule_version COMMENT "EndpointRuleVersion amends EndpointRuleVersion" AS
SELECT endpoint_version AS source_id, concat(endpoint_id, '.', amends) AS target_id FROM ${catalog}.clinical_study_standards.rule_version WHERE amends IS NOT NULL;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_applies_to__endpoint_rule_version__study_version COMMENT "EndpointRuleVersion appliesTo StudyVersion" AS
SELECT r.endpoint_version AS source_id, v.study_version_id AS target_id FROM ${catalog}.clinical_study_standards.rule_version r JOIN ${catalog}.clinical_study_standards.study_version v ON v.study_id = r.study_id AND v.sap_version = r.sap_version;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_supported_by__endpoint_rule_version__document_section COMMENT "EndpointRuleVersion supportedBy DocumentSection" AS
SELECT s.rule_id AS source_id, d.section_id AS target_id FROM ${catalog}.clinical_study_standards.rule_document_support s JOIN ${catalog}.clinical_study.doc_section d ON d.document_id = s.document_id AND d.section_number = s.section WHERE s.rule_kind = 'endpoint';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_endpoint_of__endpoint_definition__study COMMENT "EndpointDefinition endpointOf Study" AS
SELECT DISTINCT endpoint_id AS source_id, study_id AS target_id FROM ${catalog}.clinical_study_standards.rule_version;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_measures__endpoint_definition__biomedical_concept COMMENT "EndpointDefinition measures BiomedicalConcept" AS
SELECT DISTINCT endpoint_id AS source_id, biomedical_concept AS target_id FROM ${catalog}.clinical_study_standards.rule_version;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_uses_specialization__endpoint_definition__dataset_specialization COMMENT "EndpointDefinition usesSpecialization DatasetSpecialization" AS
SELECT DISTINCT endpoint_id AS source_id, dataset_specialization AS target_id FROM ${catalog}.clinical_study_standards.rule_version;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_uses_population__endpoint_definition__analysis_population COMMENT "EndpointDefinition usesPopulation AnalysisPopulation" AS
SELECT DISTINCT endpoint_id AS source_id, population AS target_id FROM ${catalog}.clinical_study_standards.rule_version;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_eligibility_of__eligibility_rule__study COMMENT "EligibilityRule eligibilityOf Study" AS
SELECT DISTINCT eligibility_rule_id AS source_id, study_id AS target_id FROM ${catalog}.clinical_study_standards.eligibility_criterion;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_applies_to__eligibility_rule__study_version COMMENT "EligibilityRule appliesTo StudyVersion" AS
SELECT DISTINCT c.eligibility_rule_id AS source_id, v.study_version_id AS target_id FROM (SELECT eligibility_rule_id, study_id, explode(split(protocol_versions, ',')) AS pv FROM ${catalog}.clinical_study_standards.eligibility_criterion) c JOIN ${catalog}.clinical_study_standards.study_version v ON v.study_id = c.study_id AND v.protocol_version = c.pv;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_supported_by__eligibility_rule__document_section COMMENT "EligibilityRule supportedBy DocumentSection" AS
SELECT s.rule_id AS source_id, d.section_id AS target_id FROM ${catalog}.clinical_study_standards.rule_document_support s JOIN ${catalog}.clinical_study.doc_section d ON d.document_id = s.document_id AND d.section_number = s.section WHERE s.rule_kind = 'eligibility';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_criterion__eligibility_rule__eligibility_criterion COMMENT "EligibilityRule hasCriterion EligibilityCriterion" AS
SELECT eligibility_rule_id AS source_id, concat(eligibility_rule_id, '.', criterion_id) AS target_id FROM ${catalog}.clinical_study_standards.eligibility_criterion;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_uses_class__eligibility_criterion__concept_class COMMENT "EligibilityCriterion usesClass ConceptClass" AS
SELECT concat(eligibility_rule_id, '.', criterion_id) AS source_id, class_id AS target_id FROM ${catalog}.clinical_study_standards.eligibility_criterion WHERE class_id IS NOT NULL;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_extends_class__concept_class__concept_class COMMENT "ConceptClass extendsClass ConceptClass" AS
SELECT class_id AS source_id, extends AS target_id FROM ${catalog}.clinical_study_standards.concept_class WHERE extends IS NOT NULL;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_root__concept_class__disease COMMENT "ConceptClass hasRoot Disease" AS
SELECT class_id AS source_id, concept_id AS target_id FROM ${catalog}.clinical_study_standards.class_root WHERE kind = 'root';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_excludes_root__concept_class__disease COMMENT "ConceptClass excludesRoot Disease" AS
SELECT class_id AS source_id, concept_id AS target_id FROM ${catalog}.clinical_study_standards.class_root WHERE kind = 'exclude_root';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_drug_class__concept_class__drug_class COMMENT "ConceptClass hasDrugClass DrugClass" AS
SELECT class_id AS source_id, concept_id AS target_id FROM ${catalog}.clinical_study_standards.class_root WHERE kind IN ('member_of_class', 'drug_class');

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_has_prohibited_effect__concept_class__drug_class COMMENT "ConceptClass hasProhibitedEffect DrugClass" AS
SELECT class_id AS source_id, concept_id AS target_id FROM ${catalog}.clinical_study_standards.class_root WHERE kind = 'physiologic_effect';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_excludes_contraindication_target__concept_class__mesh_record COMMENT "ConceptClass excludesContraindicationTarget MeshRecord" AS
SELECT class_id AS source_id, concept_id AS target_id FROM ${catalog}.clinical_study_standards.class_root WHERE kind = 'excluded_ci_target';

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_section_of__document_section__document COMMENT "DocumentSection sectionOf Document" AS
SELECT section_id AS source_id, document_id AS target_id FROM ${catalog}.clinical_study.doc_section;

CREATE OR REPLACE VIEW ${catalog}.clinical_study_graph.r_document_for__document__study COMMENT "Document documentFor Study" AS
SELECT document_id AS source_id, study_id AS target_id FROM ${catalog}.clinical_study.doc_document WHERE study_id IS NOT NULL;
